      "不可被对应\n【攻击后】将任意张手牌和盖牌移入弃牌区。然后从弃牌区选择任意数量的计略，以任意顺序执行。所选择的计略全部结算完毕后，准备下个计略。\n（如果选择的是神算那么执行的计略全部都是神算。鬼谋同之）",
    textZhG1:
      "不可被对应\n【攻击后】将任意张手牌和盖牌移入弃牌区。然后从弃牌中选择任意数量的计略，以任意顺序执行。所选择的计略全部结算完毕后，准备下个计略。\n（如果选择的是神算那么执行的计略全部都是神算）",
    textKo:
      "대응불가\n\n【공격후】당신은 손패나 덮임패에서 원하는 만큼 버림패에 옮길 수 있다. 그 후에 버림패에서 임의의 수의 계략을 원하는 순서대로 실행하고, 다음 계략을 준비한다.\n(신산을 준비했다면 모든 계략은 신산으로 처리된다)",
    textEn:
      "No Reactions\n\nAfter Attack: You may put any number of cards in your hand and discard pile into your played pile. Then, enact any number of Plans on cards in your played pile, in any order. After resolving all of them, prepare your next Plan.",
